def max_A_for_digits(digits):
    max_A = 0
    for N in range(1, 1000):
        # Instead of iterating over M, let's iterate over Q.
        # Q = floor(M/N).
        # M/N is roughly Q, so M is roughly N*Q.
        # Since M has 'digits' digits, N*Q has 'digits' digits.
        # So Q is roughly 10**(digits-1) / N.
        start_Q = 10**(digits-1) // N
        end_Q = (10**digits - 1) // N
        for Q in range(start_Q, end_Q + 1):
            A = str(Q).count('0')
            if A > max_A:
                # Check if there is an M in [NQ, N(Q+1)-1] with no zeros.
                # The range is [NQ, N(Q+1)-1].
                # We need to check if this range contains an M with 'digits' digits and no zeros.
                L = N * Q
                R = N * (Q + 1) - 1
                # To be a 'digits'-digit number, we need M >= 10**(digits-1).
                L = max(L, 10**(digits-1))
                # And M < 10**digits.
                R = min(R, 10**digits - 1)

                if L <= R:
                    # How to check if [L, R] contains an M with no zeros?
                    # Let's use a simple check.
                    # For small range, we can iterate. For large range, use the function.
                    found = False
                    if R - L < 1000:
                        for M in range(L, R + 1):
                            if '0' not in str(M):
                                found = True
                                break
                    else:
                        # Use the count_no_zeros function
                        def count_no_zeros(n):
                            if n <= 0: return 0
                            s = str(n)
                            length = len(s)
                            res = 0
                            # Count all with fewer digits
                            for i in range(1, length):
                                res += 9**i
                            # Count with same number of digits
                            for i in range(length):
                                digit = int(s[i])
                                if digit == 0:
                                    break
                                if i < length - 1:
                                    res += (digit - 1) * (9**(length - 1 - i))
                                else:
                                    res += (digit - 1)
                                if i == length - 1:
                                    res += 1
                            return res
                        if count_no_zeros(R) - count_no_zeros(L - 1) > 0:
                            found = True

                    if found:
                        max_A = A
    return max_A

for d in range(1, 8):
    print(f"{d}: {max_A_for_digits(d)}")

def find_max_A_and_Q(digits):
    max_A = 0
    best_Q = 0
    best_N = 0
    for N in range(1, 1000):
        start_Q = 10**(digits-1) // N
        end_Q = (10**digits - 1) // N
        for Q in range(start_Q, end_Q + 1):
            A = str(Q).count('0')
            if A > max_A:
                L = max(N * Q, 10**(digits-1))
                R = min(N * (Q + 1) - 1, 10**digits - 1)
                if L <= R:
                    def count_no_zeros(n):
                        if n <= 0: return 0
                        s = str(n)
                        length = len(s)
                        res = 0
                        for i in range(1, length):
                            res += 9**i
                        for i in range(length):
                            digit = int(s[i])
                            if digit == 0: break
                            if i < length - 1:
                                res += (digit - 1) * (9**(length - 1 - i))
                            else:
                                res += (digit - 1)
                            if i == length - 1:
                                res += 1
                        return res
                    if count_no_zeros(R) - count_no_zeros(L - 1) > 0:
                        max_A = A
                        best_Q = Q
                        best_N = N
    return max_A, best_Q, best_N

